bool distinct(const std::vector<P>&b,std::array<size_t,4>v){for(int i=0;i<4;++i)for(int j=0;j<i;++j)if(b[v[i]].x==b[v[j]].x)return false;return true;}
Solve4 strict(const Curve&c,const std::vector<P>&b,const Table&t,P q){for(size_t k=0;k<b.size();++k)for(size_t l=0;l<b.size();++l){if(b[k].x==b[l].x)continue;P v=c.add(q,c.neg(c.add(b[k],b[l])));auto it=t.find(c.key(v));if(it!=t.end())for(Pair p:it->second){std::array<size_t,4>ix{p.i,p.j,k,l};if(distinct(b,ix))return {true,ix};}}return {};}
Solve4 reference(const Curve&c,const std::vector<P>&b,P q){for(size_t i=0;i<b.size();++i)for(size_t j=i+1;j<b.size();++j)for(size_t k=j+1;k<b.size();++k)for(size_t l=k+1;l<b.size();++l){std::array<size_t,4>ix{i,j,k,l};if(distinct(b,ix)&&c.add(c.add(c.add(b[i],b[j]),b[k]),b[l])==q)return {true,ix};}return {};}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("usage: strict4 OUTPUT_DIRECTORY");std::filesystem::path dir=argv[1];std::filesystem::create_directories(dir);std::ofstream out(dir/"results.jsonl"),cert(dir/"certificates.jsonl"),sum(dir/"summary.csv");sum<<"p,seed,curve,B,base_points,distinct_abscissae,natural_targets,natural_hits,control_available,control_pass,mitm_online_ga,reference_ga\n";U curveid=24,hits=0,controls=0,rows=0;
for(U p:{251ULL,509ULL,1021ULL,2039ULL,4093ULL})for(U seed=1;seed<=3;++seed){++curveid;auto z=fixture(p,false,seed);auto&c=z.c;U B=1;while(B*B*B*B*B<p)++B;std::vector<P>b;std::set<U>xs;for(U x=0;x<B;++x){auto it=c.roots.find(c.rhs(x));if(it!=c.roots.end())for(U y:it->second){b.push_back({x,y,false});xs.insert(x);}}c.f.reset();auto t=pairtable(c,b);Cost setup=c.f.cost;Rng rng{20261018+p+seed};U nh=0,ga=0,refga=0;bool cp=false;
for(U tid=0;tid<33;++tid){bool planted=tid==32;P q;U known=0;if(planted){if(xs.size()<4)continue;U prior=~U(0),used=0;for(P v:b)if(v.x!=prior){q=c.add(q,v);prior=v.x;if(++used==4)break;}if(q.inf)throw std::runtime_error("strict control sums to infinity");}else{known=1+rng.range(z.r-1);q=c.mul(known,z.g);}c.f.reset();auto a=strict(c,b,t,q);Cost ac=c.f.cost;c.f.reset();auto r=reference(c,b,q);Cost rc=c.f.cost;if(a.found!=r.found)throw std::runtime_error("strict MITM/reference mismatch");if(planted&&!a.found)throw std::runtime_error("strict positive control missed");if(a.found){if(!distinct(b,a.i))throw std::runtime_error("not strict arity four");check4(c,b,a,q,B);if(planted){++controls;cp=true;}else{++nh;++hits;}cert<<"{\"item\":14,\"curve_id\":"<<curveid<<",\"target_id\":"<<tid<<",\"target\":"<<pj(q)<<",\"points\":[";for(int j=0;j<4;++j){if(j)cert<<',';cert<<pj(b[a.i[j]]);}cert<<"],\"distinct_abscissae\":true}\n";}ga+=ac.ga;refga+=rc.ga;++rows;out<<"{\"item\":14,\"curve_id\":"<<curveid<<",\"p\":"<<p<<",\"a\":"<<c.a<<",\"b\":"<<c.b<<",\"r\":"<<z.r<<",\"B\":"<<B<<",\"target_id\":"<<tid<<",\"planted\":"<<planted<<",\"target\":"<<pj(q)<<",\"known_k\":"<<(planted?"null":std::to_string(known))<<",\"found\":"<<a.found<<",\"reference_agreement\":true,\"pair_setup\":"<<cj(setup)<<",\"mitm_online\":"<<cj(ac)<<",\"reference\":"<<cj(rc)<<"}\n";}
sum<<p<<','<<seed<<','<<curveid<<','<<B<<','<<b.size()<<','<<xs.size()<<",32,"<<nh<<','<<(xs.size()>=4)<<','<<cp<<','<<ga<<','<<refga<<'\n';}
std::cout<<"PASS "<<rows<<" strict-arity oracle/reference comparisons, "<<hits<<"/480 natural hits, "<<controls<<" available positive controls; all four abscissae distinct.\n";return 0;}catch(std::exception&e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
